urlset:
{%- if config.url %}

  {{ config.url | uriencode }}
  {{ sNow | formatDate }}
  weekly
  0.9

{%- endif %}

{%- for post in posts %}

  {{ post.permalink | uriencode }}
  {%- if post.updated %}
  {{ post.updated | formatDate }}
  {%- elif post.date %}
  {{ post.date | formatDate }}
  {%- endif %}
  monthly
  0.7

{%- endfor %}

{%- for tag in tags %}

  {{ tag.permalink | uriencode }}
  {{ sNow | formatDate }}
  weekly
  0.5

{%- endfor %}

{%- for cat in categories %}

  {{ cat.permalink | uriencode }}
  {{ sNow | formatDate }}
  weekly
  0.5

{%- endfor %}
